pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address addr, uint256 putAmount, uint256 collectAmount, uint128 unlockTime) public {
        // Ensure that putAmount is not zero to allow putting funds
        vm.assume(putAmount > 0);
        // Restrict collectAmount to be at least 1 wei to make the call meaningful
        vm.assume(collectAmount > 0);
        // Ensure unlockTime is not too far in the future to keep the test reasonable
        vm.assume(unlockTime <= block.timestamp + 1000 days);

        // Precondition: fund the contract so that we can possibly collect
        vm.deal(address(this), putAmount);
        (bool success,) = address(c).call{value: putAmount}("Put", abi.encode(unlockTime));
        require(success, "Put failed");

        uint256 minSumBefore = c.MinSum();
        // Record the timestamp after Put
        vm.warp(block.timestamp + 1); // Ensure timestamp advances

        // Attempt Collect
        (bool collectSuccess,) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));
        uint256 minSumAfter = c.MinSum();

        // The MinSum should never increase
        assertTrue(minSumAfter <= minSumBefore, "MinSum increased");
    }
}

