import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address user, uint256 unlockTimeOffset, uint256 putAmount, uint256 collectAmount) public {
        // Ensure user is not the contract itself (to avoid oddities)
        vm.assume(user != address(0) && user != address(c));
        // Bound inputs to reasonable ranges
        unlockTimeOffset = bound(unlockTimeOffset, 0, 1000000);
        putAmount = bound(putAmount, 0.1 ether, 10 ether);
        collectAmount = bound(collectAmount, 0.1 ether, 10 ether);
        // Fund the user and the contract
        vm.deal(user, putAmount);
        // User calls Put to deposit
