        c.Put{value: putAmount}(block.timestamp + unlockTimeOffset);
        // Check that user has balance
        (uint256 balance, ) = c.Acc(user);
        vm.assume(balance >= collectAmount);
        // Try Collect but force the external call to fail by setting user's balance to 0
        vm.deal(user, 0);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));
        // If the call failed (should fail because user cannot receive ether)
        if (!success) {
            (uint256 balanceAfter, ) = c.Acc(user);
            assertTrue(balanceAfter == balance, "Balance should stay same after failed Collect");
        }
    }
