pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, uint256 putAmount, uint256 unlockTimeDelta, uint256 collectAmount) public {
        // Bound inputs to avoid overflow in arithmetic within the test, but not the contract
        vm.assume(sender != address(0));
        putAmount = bound(putAmount, 0, 1e24);
        unlockTimeDelta = bound(unlockTimeDelta, 0, 365 days);
        collectAmount = bound(collectAmount, 0, 1e24);

        // Give sender some ether
        vm.deal(sender, 100 ether);

        // Call Put to set up some balance and unlock time
        vm.prank(sender);
        c.Put{value: putAmount}(block.timestamp + unlockTimeDelta);

        // Read the sender's balance before Collect
        (uint256 unlockTimeBefore, uint256 balanceBefore) = c.Acc(sender);

        // Warp to after the unlock time so the Collect can succeed
        vm.warp(unlockTimeBefore + 1);

        // Call Collect and track if it reverts
        bool collectReverted;
        try c.Collect{value: 0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read the sender's balance after Collect
        (, uint256 balanceAfter) = c.Acc(sender);

        // General rule: If Collect succeeded, then balanceAfter == balanceBefore - collectAmount
        // If Collect reverted, balanceAfter == balanceBefore (the state should not change)
        assertTrue(collectReverted || balanceAfter + collectAmount == balanceBefore, "Property violation: balance not updated correctly");
    }
}

